contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length == v.length);
        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (_tos.length > 0) {
            if (!reverted) {
                // If the call succeeded, all transferFrom targets must have succeeded.
                // We can verify this by checking that the last target's transferFrom succeeds.
                (bool lastSuccess,) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, _tos[_tos.length - 1], v[_tos.length - 1]));
                assert(lastSuccess || !reverted);
            }
        }
        // General rule: the function must not revert for a single-element success case? 
        // Instead, assert that for a single-element array where the underlying call succeeds, transfer returns true.
        // But we cannot easily simulate a successful transferFrom without a mock contract.
        // So we use a rule about revert behavior: if any element's v is zero and the target call fails, it should revert.
        // Simpler: assert that if the array is non-empty and the first target call fails, transfer reverts.
        if (_tos.length == 1) {
            (bool firstSuccess,) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, _tos[0], v[0]));
            assert(firstSuccess || reverted);
        }
    }

    receive() external payable {}
}

