contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address callee, address[] memory tos, uint[] memory v) public payable {
        require(tos.length > 0);
        require(v.length >= tos.length);

        bool reverted;
        try c.transfer(from, callee, tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !_allForwarded(callee, from, tos, v));
    }

    function _allForwarded(address callee, address from, address[] memory tos, uint[] memory v) private view returns (bool) {
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < tos.length; i++) {
            (bool ok, bytes memory ret) = callee.staticcall(abi.encodeWithSelector(id, from, tos[i], v[i]));
            if (!ok) return false;
            if (ret.length != 0) {
                if (!abi.decode(ret, (bool))) return false;
            }
        }
        return true;
    }
}

